    [Fact]
    public async Task Api_requires_bearer_viewer_cannot_import_unknown_json_and_pagination_validation()
    { await using var h = await Host.Start(); using var c = h.Client(); using (var r = await c.GetAsync("/api/items")) Assert.Equal(HttpStatusCode.Unauthorized, r.StatusCode); c.DefaultRequestHeaders.Add("Cookie", "dt_session=" + await h.Login("admin", AuthClientType.Web)); using (var r = await c.GetAsync("/api/items")) Assert.Equal(HttpStatusCode.Forbidden, r.StatusCode); c.DefaultRequestHeaders.Remove("Cookie"); await h.F.Base.Grant(AuthRole.Viewer); c.DefaultRequestHeaders.Authorization = new("Bearer", await h.Login("user", AuthClientType.Mobile)); using (var r = await c.PostAsJsonAsync("/api/item-imports/preview", h.F.Request())) Assert.Equal(HttpStatusCode.Forbidden, r.StatusCode); c.DefaultRequestHeaders.Authorization = new("Bearer", await h.Login("admin", AuthClientType.Mobile)); using (var r = await c.GetAsync("/api/items?pageSize=101")) Assert.Equal((HttpStatusCode)422, r.StatusCode); using (var r = await c.PostAsync("/api/item-imports/preview", new StringContent("{broken", System.Text.Encoding.UTF8, "application/json"))) Assert.Equal(HttpStatusCode.BadRequest, r.StatusCode); }
    [Fact]
    public async Task Api_preview_start_chunk_replay_list_detail_snapshot_and_safe_upstream()
    { await using var h = await Host.Start(); using var c = h.Client(); c.DefaultRequestHeaders.Authorization = new("Bearer", await h.Login("admin", AuthClientType.Mobile)); var req = h.F.Request(); var p = await c.PostAsJsonAsync("/api/item-imports/preview", req); p.EnsureSuccessStatusCode(); Assert.Contains("no-store", p.Headers.CacheControl!.ToString(), StringComparison.Ordinal); var preview = (await p.Content.ReadFromJsonAsync<ItemPreview>())!; c.DefaultRequestHeaders.Add("Idempotency-Key", "start"); var start = await c.PostAsJsonAsync("/api/item-imports", new InventoryWeb.StartRequest(req, preview.Revision, preview.PreviewHash, true)); start.EnsureSuccessStatusCode(); var j = (await start.Content.ReadFromJsonAsync<ItemImportJob>())!; c.DefaultRequestHeaders.Remove("Idempotency-Key"); using (var r = await c.PostAsJsonAsync("/api/item-imports/" + j.JobId + "/chunks", new InventoryWeb.ChunkRequest(0))) Assert.Equal((HttpStatusCode)422, r.StatusCode); c.DefaultRequestHeaders.Add("Idempotency-Key", "chunk"); var chunk = await c.PostAsJsonAsync("/api/item-imports/" + j.JobId + "/chunks", new InventoryWeb.ChunkRequest(0)); chunk.EnsureSuccessStatusCode(); Assert.Equal("COMPLETE", (await chunk.Content.ReadFromJsonAsync<ItemImportJob>())!.State); var items = (await c.GetFromJsonAsync<ItemList>("/api/items"))!; Assert.Single(items.Items); var detail = await c.GetFromJsonAsync<ItemRecord>("/api/items/" + items.Items[0].ItemId); Assert.Equal("00001", detail!.SourceCode); c.DefaultRequestHeaders.Remove("Idempotency-Key"); c.DefaultRequestHeaders.Add("Idempotency-Key", "snapshot"); h.F.Store.FailNext = true; using (var r = await c.PostAsJsonAsync("/api/stock-balances", h.F.Stock(null, null))) { Assert.Equal(HttpStatusCode.ServiceUnavailable, r.StatusCode); Assert.DoesNotContain("PRIVATE-INVENTORY-CANARY", await r.Content.ReadAsStringAsync(), StringComparison.Ordinal); } using (var r = await c.PostAsJsonAsync("/api/stock-balances", h.F.Stock(null, null))) r.EnsureSuccessStatusCode(); Assert.Equal("UNKNOWN", (await c.GetFromJsonAsync<StockList>("/api/stock-balances"))!.Items.Single().StockStatus); }
    [Fact]
    public async Task Razor_import_validation_preview_start_chunk_and_two_descriptions_render_with_csrf()
    { await using var h = await Host.Start(); using var c = h.Client(); c.DefaultRequestHeaders.Add("Cookie", "dt_session=" + await h.Login("admin", AuthClientType.Web)); var html = await c.GetStringAsync("/Items/Import"); using (var r = await c.PostAsync("/Items/Import?handler=Preview", new FormUrlEncodedContent(new Dictionary<string, string> { { "Reason", "fixture" } }))) Assert.Equal(HttpStatusCode.BadRequest, r.StatusCode); var values = Form(html, h.F.Request()); values["Reason"] = ""; using (var r = await c.PostAsync("/Items/Import?handler=Preview", new FormUrlEncodedContent(values))) { Assert.Equal((HttpStatusCode)422, r.StatusCode); Assert.Contains("DRAFT_DEMO", await r.Content.ReadAsStringAsync(), StringComparison.Ordinal); } values = Form(html, h.F.Request()); using (var r = await c.PostAsync("/Items/Import?handler=Preview", new FormUrlEncodedContent(values))) { r.EnsureSuccessStatusCode(); html = await r.Content.ReadAsStringAsync(); Assert.Contains("ADD", html, StringComparison.Ordinal); } values = Form(html, h.F.Request()); values["PreviewHash"] = Field(html, "PreviewHash"); values["Revision"] = Field(html, "Revision"); values["Confirm"] = "true"; using (var r = await c.PostAsync("/Items/Import?handler=Start", new FormUrlEncodedContent(values))) { r.EnsureSuccessStatusCode(); html = await r.Content.ReadAsStringAsync(); Assert.Contains("VALIDATED", html, StringComparison.Ordinal); } var fields = new Dictionary<string, string> { { "__RequestVerificationToken", Field(html, "__RequestVerificationToken") }, { "JobId", Field(html, "JobId") }, { "ExpectedProgress", Field(html, "ExpectedProgress") }, { "RequestKey", Field(html, "RequestKey") } }; using (var r = await c.PostAsync("/Items/Import?handler=Chunk", new FormUrlEncodedContent(fields))) { r.EnsureSuccessStatusCode(); Assert.Contains("COMPLETE", await r.Content.ReadAsStringAsync(), StringComparison.Ordinal); } var item = h.F.Store.State.Items.Single(); html = WebUtility.HtmlDecode(await c.GetStringAsync("/Items/Detail/" + item.ItemId)); Assert.Contains("Mô tả Item GIẢ", html, StringComparison.Ordinal); Assert.Contains("Mô tả conversion GIẢ", html, StringComparison.Ordinal); Assert.Contains("UNKNOWN", html, StringComparison.Ordinal); }
    [Fact]
    public async Task Razor_viewer_read_scoped_but_import_denied_and_stock_update_denied()
    { await using var h = await Host.Start(); await h.F.Import(h.F.Request()); await h.F.Base.Grant(AuthRole.Viewer); using var c = h.Client(); c.DefaultRequestHeaders.Add("Cookie", "dt_session=" + await h.Login("user", AuthClientType.Web)); c.DefaultRequestHeaders.Accept.Add(new("text/html")); var html = await c.GetStringAsync("/Items"); Assert.Contains("00001", html, StringComparison.Ordinal); using (var r = await c.GetAsync("/Items/Import")) { Assert.Equal(HttpStatusCode.Redirect, r.StatusCode); Assert.Equal("/Account/AccessDenied", r.Headers.Location!.OriginalString); } html = await c.GetStringAsync("/Stock"); Assert.Contains("UNKNOWN", html, StringComparison.Ordinal); Assert.DoesNotContain("name=\"Quantity\"", html, StringComparison.Ordinal); }
    [Fact]
    public async Task Razor_stock_post_invalid_number_preserves_input_key_then_unknown_snapshot_success()
    { await using var h = await Host.Start(); await h.F.Import(h.F.Request()); using var c = h.Client(); c.DefaultRequestHeaders.Add("Cookie", "dt_session=" + await h.Login("admin", AuthClientType.Web)); var html = await c.GetStringAsync("/Stock"); var r = h.F.Stock(null, null); var values = new Dictionary<string, string> { { "__RequestVerificationToken", Field(html, "__RequestVerificationToken") }, { "RequestKey", Field(html, "RequestKey") }, { "ItemId", r.ItemId }, { "LocationId", r.LocationId }, { "Unit", r.Unit }, { "Quantity", "bad" }, { "Minimum", "" }, { "Source", r.Source }, { "Reason", r.Reason }, { "AsOf", r.AsOf.ToString("O") }, { "ExpectedVersion", "0" } }; using (var response = await c.PostAsync("/Stock", new FormUrlEncodedContent(values))) { Assert.Equal((HttpStatusCode)422, response.StatusCode); html = await response.Content.ReadAsStringAsync(); Assert.Equal(values["RequestKey"], Field(html, "RequestKey")); Assert.Equal("bad", Field(html, "Quantity")); } values["Quantity"] = ""; using (var response = await c.PostAsync("/Stock", new FormUrlEncodedContent(values))) { response.EnsureSuccessStatusCode(); Assert.Contains("UNKNOWN", await response.Content.ReadAsStringAsync(), StringComparison.Ordinal); } Assert.Null(h.F.Store.State.Balances.Single().Quantity); }
    [Fact]
    public async Task Multipart_file_preview_preserves_hash_and_start_matches_parsed_source()
    { await using var h = await Host.Start(); using var c = h.Client(); c.DefaultRequestHeaders.Authorization = new("Bearer", await h.Login("admin", AuthClientType.Mobile)); var r = h.F.Request(); using var body = new MultipartFormDataContent(); var json = new JsonSerializerOptions(JsonSerializerDefaults.Web); var bytes = JsonSerializer.SerializeToUtf8Bytes(r.Document, json); body.Add(new ByteArrayContent(bytes), "file", "GIẢ.json"); body.Add(new StringContent(JsonSerializer.Serialize(r.Groups, json)), "groups"); body.Add(new StringContent("[]"), "decisions"); body.Add(new StringContent(r.Reason), "reason"); using var response = await c.PostAsync("/api/item-imports/preview-file", body); response.EnsureSuccessStatusCode(); using var doc = JsonDocument.Parse(await response.Content.ReadAsStringAsync()); var parsed = doc.RootElement.GetProperty("document").Deserialize<ItemDocument>(json)!; var p = doc.RootElement.GetProperty("preview").Deserialize<ItemPreview>(json)!; Assert.Equal(Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(bytes)), parsed.SourceHash); c.DefaultRequestHeaders.Add("Idempotency-Key", "file-start"); using var start = await c.PostAsJsonAsync("/api/item-imports", new InventoryWeb.StartRequest(r with { Document = parsed }, p.Revision, p.PreviewHash, true)); start.EnsureSuccessStatusCode(); Assert.Contains("ITEMS_VTHH20_V1", h.F.Store.State.Jobs.Single().DecisionsJson, StringComparison.Ordinal); }
    [Fact]
    public async Task Multipart_invalid_json_is_validation_and_unknown_fields_rejected()
    { await using var h = await Host.Start(); using var c = h.Client(); c.DefaultRequestHeaders.Authorization = new("Bearer", await h.Login("admin", AuthClientType.Mobile)); var request = h.F.Request(); var payload = JsonSerializer.SerializeToNode(request, new JsonSerializerOptions(JsonSerializerDefaults.Web))!; payload["isApproved"] = true; using (var response = await c.PostAsJsonAsync("/api/item-imports/preview", payload)) Assert.Equal(HttpStatusCode.BadRequest, response.StatusCode); using var body = new MultipartFormDataContent(); body.Add(new ByteArrayContent(JsonSerializer.SerializeToUtf8Bytes(request.Document, new JsonSerializerOptions(JsonSerializerDefaults.Web))), "file", "GIẢ.json"); body.Add(new StringContent("invalid"), "groups"); body.Add(new StringContent("[]"), "decisions"); body.Add(new StringContent("GIẢ"), "reason"); using (var response = await c.PostAsync("/api/item-imports/preview-file", body)) Assert.Equal((HttpStatusCode)422, response.StatusCode); Assert.Equal(0, h.F.Store.Writes); }
    [Fact]
    public async Task Razor_group_choices_and_duplicate_merge_decision_form_revalidate_then_commit()
    { await using var h = await Host.Start(); using var c = h.Client(); c.DefaultRequestHeaders.Add("Cookie", "dt_session=" + await h.Login("admin", AuthClientType.Web)); var html = await c.GetStringAsync("/Items/Import"); var req = h.F.Request(2, true); var values = Form(html, req); using (var r = await c.PostAsync("/Items/Import?handler=Preview", new FormUrlEncodedContent(values))) { r.EnsureSuccessStatusCode(); html = await r.Content.ReadAsStringAsync(); Assert.Contains("GroupRows[0].CategoryId", html, StringComparison.Ordinal); Assert.Contains("DuplicateRows[0].Mode", html, StringComparison.Ordinal); Assert.DoesNotContain("handler=Start", html, StringComparison.Ordinal); } values = Form(html, req); values["GroupRows[0].SourceGroup"] = "GIẢ"; values["GroupRows[0].CategoryId"] = "CAT-CHILD"; values["GroupRows[0].Tracking"] = "YES"; values["DuplicateRows[0].SourceCode"] = "CĐKEM"; values["DuplicateRows[0].Mode"] = "MERGE"; values["DuplicateRows[0].Reason"] = "Quyết định GIẢ đồng nhất20cột"; using (var r = await c.PostAsync("/Items/Import?handler=Preview", new FormUrlEncodedContent(values))) { r.EnsureSuccessStatusCode(); html = await r.Content.ReadAsStringAsync(); Assert.Contains("handler=Start", html, StringComparison.Ordinal); } values["__RequestVerificationToken"] = Field(html, "__RequestVerificationToken"); values["PreviewHash"] = Field(html, "PreviewHash"); values["Revision"] = Field(html, "Revision"); values["Confirm"] = "true"; using (var r = await c.PostAsync("/Items/Import?handler=Start", new FormUrlEncodedContent(values))) r.EnsureSuccessStatusCode(); Assert.Equal(1, h.F.Store.State.Jobs.Single().PlannedCount); Assert.Contains("MERGE", h.F.Store.State.Jobs.Single().DecisionsJson, StringComparison.Ordinal); }
    private static Dictionary<string, string> Form(string html, ItemImportRequest r) => new() { { "__RequestVerificationToken", Field(html, "__RequestVerificationToken") }, { "RequestKey", Field(html, "RequestKey") }, { "DocumentJson", JsonSerializer.Serialize(r.Document, new JsonSerializerOptions(JsonSerializerDefaults.Web)) }, { "GroupsJson", JsonSerializer.Serialize(r.Groups, new JsonSerializerOptions(JsonSerializerDefaults.Web)) }, { "DecisionsJson", "[]" }, { "Reason", r.Reason } };
    private static string Field(string html, string name) { var m = Regex.Match(html, "name=\"" + name + "\"[^>]*value=\"([^\"]*)\""); Assert.True(m.Success, "Missing: " + name); return WebUtility.HtmlDecode(m.Groups[1].Value); }
    private sealed class Host(WebApplication app, InventoryFixture f, string address) : IAsyncDisposable
    {
        public InventoryFixture F { get; } = f; public HttpClient Client() => new(new HttpClientHandler { AllowAutoRedirect = false }) { BaseAddress = new(address) };
        public async Task<string> Login(string name, AuthClientType type) { var r = await app.Services.GetRequiredService<AuthApplicationService>().LoginAsync(new(name, "fake-password", type, false, "inventory-http")); Assert.Equal(LoginStatus.Success, r.Status); return r.AccessToken!; }
        public static async Task<Host> Start()
        { var f = await InventoryFixture.Start(); var b = WebApplication.CreateBuilder(new WebApplicationOptions { EnvironmentName = "Testing", ApplicationName = typeof(InventoryWeb).Assembly.GetName().Name, ContentRootPath = AppContext.BaseDirectory }); b.WebHost.UseKestrel(); b.Logging.ClearProviders(); b.Services.AddRazorPages(); b.Services.AddSingleton(f.Service); b.Services.AddSingleton<IAuthSystemStore>(f.Base.Auth); b.Services.AddSingleton<IPasswordHashService>(new TestPasswordHashService()); b.Services.AddSingleton(new AuthPolicyOptions()); b.Services.AddSingleton<TimeProvider>(f.Base.Clock); b.Services.AddSingleton<AuthApplicationService>(); b.Services.AddAuthentication(OpaqueSessionAuthenticationHandler.SchemeName).AddScheme<AuthenticationSchemeOptions, OpaqueSessionAuthenticationHandler>(OpaqueSessionAuthenticationHandler.SchemeName, _ => { }); b.Services.AddAuthorization(); var app = b.Build(); app.Urls.Add("http://127.0.0.1:0"); app.UseTask005SessionAuthentication(); app.UseAuthorization(); app.MapTask010InventoryApi(); app.MapRazorPages(); await app.StartAsync(); return new(app, f, app.Services.GetRequiredService<IServer>().Features.Get<IServerAddressesFeature>()!.Addresses.Single()); }
        public async ValueTask DisposeAsync() { await app.StopAsync(); await app.DisposeAsync(); }
    }
